#include <iostream>
#include <vector>
#include <functional>
#include <queue>
using namespace std;

class AsyncStream {
    vector<function<void(int)>> subscribers;
    queue<function<void()>> tasks;
public:
    void subscribe(function<void(int)> cb) { subscribers.push_back(cb); }

    void push(int val) {
        tasks.push([this, val]() {
            for (auto& cb : subscribers) cb(val);
        });
    }

    void processNext() {
        if (!tasks.empty()) { tasks.front()(); tasks.pop(); }
    }

    void processAll() {
        while (!tasks.empty()) processNext();
    }
};

int main() {
    AsyncStream stream;
    stream.subscribe([](int v) { cout << "Got: " << v << endl; });
    stream.push(10);
    stream.push(20);
    stream.push(30);
    stream.processAll();
    return 0;
}
